// Parse and validate the incoming request
const body = $input.first().json.body ?? $input.first().json;

if (!body.addresses || !Array.isArray(body.addresses) || body.addresses.length === 0) {
  throw new Error('Request must include "addresses" array of email addresses to pull.');
}

const addresses = body.addresses.map(a => a.trim().toLowerCase());
const outputPath = body.output_path ?? `/tmp/email_export_${Date.now()}.pdf`;
const maxResults = body.max_results ?? 200;

return [{ json: { addresses, outputPath, maxResults, addressList: addresses.join(',') } }];

// Build Gmail search query from the address list
// This finds all emails FROM or TO any of the specified addresses
const addresses = $input.first().json.addresses;

const fromTerms = addresses.map(a => `from:${a}`);
const toTerms   = addresses.map(a => `to:${a}`);
const query = [...fromTerms, ...toTerms].join(' OR ');

return [{ json: { ...$input.first().json, gmailQuery: query } }];

// Parse raw Gmail message objects into clean structured data
const config = $('Parse Request').first().json;

const messages = [];

for (const item of $input.all()) {
  const msg = item.json;

  // Extract headers
  const headers = {};
  const rawHeaders = msg.payload?.headers ?? [];
  for (const h of rawHeaders) {
    headers[h.name.toLowerCase()] = h.value;
  }

  // Extract body text (prefer plain text, fall back to html stripped)
  let body = '';

  function extractBody(part) {
    if (!part) return '';
    if (part.mimeType === 'text/plain' && part.body?.data) {
      return Buffer.from(part.body.data, 'base64').toString('utf-8');
    }
    if (part.mimeType === 'text/html' && part.body?.data && !body) {
      const html = Buffer.from(part.body.data, 'base64').toString('utf-8');
      // Strip HTML tags for a plain text fallback
      return html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    }
    if (part.parts) {
      for (const sub of part.parts) {
        const result = extractBody(sub);
        if (result) return result;
      }
    }
    return '';
  }

  body = extractBody(msg.payload);

  // Strip quoted reply chains (lines starting with > or "On ... wrote:")
  const lines = body.split('\n');
  const cleanLines = [];
  for (const line of lines) {
    if (line.trim().startsWith('>')) break;
    if (/^On .+ wrote:/.test(line.trim())) break;
    cleanLines.push(line);
  }
  body = cleanLines.join('\n').trim();

  messages.push({
    id:      msg.id,
    subject: headers['subject'] ?? '(No Subject)',
    from:    headers['from']    ?? 'Unknown',
    to:      headers['to']      ?? '',
    date:    headers['date']    ? new Date(headers['date']).toISOString() : new Date().toISOString(),
    body:    body || '(no body content)'
  });
}

// Sort oldest first
messages.sort((a, b) => new Date(a.date) - new Date(b.date));

return [{ json: { messages, config } }];

// Validate we have messages and prepare the shell command
const { messages, config } = $input.first().json;

if (!messages || messages.length === 0) {
  throw new Error(`No messages found for addresses: ${config.addresses.join(', ')}`);
}

// Write messages JSON to a temp file for the Python script
const fs = require('fs');
const tmpJsonPath = `/tmp/emails_${Date.now()}.json`;
fs.writeFileSync(tmpJsonPath, JSON.stringify(messages, null, 2), 'utf-8');

// Build the shell command
const cmd = `python3 /opt/n8n-scripts/email_to_pdf.py \
  --output "${config.outputPath}" \
  --addresses "${config.addressList}" \
  < "${tmpJsonPath}" \
  && echo SUCCESS \
  && rm -f "${tmpJsonPath}"`;

return [{ json: { cmd, outputPath: config.outputPath, messageCount: messages.length, addresses: config.addresses } }];

// Check execution result and build response
const result    = $input.first().json;
const prevNode  = $('Prepare Shell Command').first().json;

const success = (result.exitCode === 0) && result.stdout?.includes('SUCCESS');

if (!success) {
  throw new Error(`PDF generation failed:\n${result.stderr || result.stdout}`);
}

return [{
  json: {
    success: true,
    message: `PDF exported successfully`,
    pdf_path: prevNode.outputPath,
    message_count: prevNode.messageCount,
    addresses: prevNode.addresses,
    generated_at: new Date().toISOString()
  }
}];
